mapper.select:
SELECT A.FINPROD_ID finprodId, A.FINPROD_MARKET_ID finprodMarketId, A.FINPROD_NAME finprodName, A.CCY ccy, A.VDATE vdate, A.MDATE mdate, T.CUSTOMER_NAME manager, A.CALENDAR_ID calendarId, A.CAPI_INCOME_FEATURE capiIncomeFeature, /*A.TRUSTEE_ID trusteeId,*/ A.ISSUE_AMT issueAmt, A.FINPROD_TYPE2, B.TYPE_6 category, B.TYPE_7 type,
B.TYPE_9 type9, B.TYPE_10 type10, B.TYPE_11 type11, B.TYPE_12 type12,
FPR.recommender recommender, FPR.recommenderName recommenderName,
(CASE WHEN C.PUR_SPEED = 0 THEN 'T+0' ELSE 'T+1' END) transMode, D.CASH_OUT_NO cmsId, (CASE WHEN A.FINPROD_TYPE2 = #{ TYPE_TOUGUAN_F17, jdbcType = VARCHAR} THEN 'N' ELSE 'Y' END ) parentPlan, D.TRIAL_NO, A.CONTRACT_NO, A.INVEST_ADVISER, T1.CUSTOMER_NAME issuer, T2.CUSTOMER_NAME trusteeId FROM FIN_PRODUCT A
LEFT JOIN ( SELECT FPR.FINPROD_ID, listagg(FPR.RECOMMENDER,'，') within group(order by FPR.RECOMMENDER) recommender, listagg(MCP.COUNTER_NAME,'，') within group(order by FPR.RECOMMENDER) recommenderName FROM FIN_PRODUCT_RECOMMENT FPR LEFT JOIN MST_COUNTER_PARTY MCP ON FPR.RECOMMENDER = MCP.COUNTER_ID GROUP BY FPR.FINPROD_ID ) FPR ON FPR.FINPROD_ID = A.FINPROD_ID
LEFT JOIN MST_CUSTOMER_INFO T ON T.CUSTOMER_ID = A.MANAGER LEFT JOIN MST_CUSTOMER_INFO T1 ON T1.CUSTOMER_ID = A.ISSUER LEFT JOIN MST_CUSTOMER_INFO T2 ON T2.CUSTOMER_ID = A.TRUSTEE_ID, FIN_PRODUCT_TYPE B, FIN_PRODUCT_ADD C, PA_FIN_PRODUCT D WHERE A.FINPROD_ID = B.FINPROD_ID AND A.FINPROD_ID = C.FINPROD_ID AND A.FINPROD_ID = D.FINPROD_ID
AND A.FINPROD_MARKET_ID LIKE CONCAT(CONCAT('%',#{finprodMarketId}),'%')
#{type10,jdbcType=VARCHAR}
#{type11,jdbcType=VARCHAR}
#{type12,jdbcType=VARCHAR}
#{type9,jdbcType=VARCHAR}
#{category,jdbcType=VARCHAR}
#{type,jdbcType=VARCHAR}
AND C.PUR_SPEED = DECODE(#{transMode,jdbcType=VARCHAR},'T+0',0,'T+1',1)
AND A.CCY = #{ccy,jdbcType=VARCHAR}
AND A.FINPROD_TYPE2 in(#{ TYPE_TOUGUAN_F27, jdbcType = VARCHAR})
AND A.FINPROD_TYPE2 in(#{ TYPE_TOUGUAN_F17, jdbcType = VARCHAR})
AND A.FINPROD_TYPE2 in(#{ TYPE_TOUGUAN_F17, jdbcType = VARCHAR},#{ TYPE_TOUGUAN_F27, jdbcType = VARCHAR})
AND A.PROFIT_TYPE = #{PROFIT_TYPE_02, jdbcType = VARCHAR}
AND A.VDATE >= DATE(#{startVDate})
AND A.VDATE >= DATE(#{endVDate})
AND A.MDATE >= DATE(#{startMDate})
AND A.MDATE >= DATE(#{endMDate})
AND A.MANAGER = #{manager,jdbcType=VARCHAR}
AND A.ISSUER = #{issuer,jdbcType=VARCHAR}
AND A.TRUSTEE_ID = #{trusteeId,jdbcType=VARCHAR}
